fn cos_authorization_with_query(access_key_id: &str, access_key_secret: &str, host: &str, query: &str) -> Result<String, String> {
    let start = Utc::now().timestamp() - 1; let sign_time = format!("{start};{}", start + 900); let canonical_query = query.split('&').filter(|item| !item.is_empty()).collect::<Vec<_>>().join("&"); let canonical_request = format!("get\n/\n{canonical_query}\n\nhost={host}\n"); let mut key_mac: Hmac<Sha1> = <Hmac<Sha1> as Mac>::new_from_slice(access_key_secret.as_bytes()).map_err(|error| error.to_string())?; key_mac.update(sign_time.as_bytes()); let sign_key = hex::encode(key_mac.finalize().into_bytes()); let string_to_sign = format!("sha1\n{sign_time}\n{:x}\n", Sha1::digest(canonical_request.as_bytes())); let mut sign_mac: Hmac<Sha1> = <Hmac<Sha1> as Mac>::new_from_slice(sign_key.as_bytes()).map_err(|error| error.to_string())?; sign_mac.update(string_to_sign.as_bytes()); Ok(format!("q-sign-algorithm=sha1&q-ak={}&q-sign-time={sign_time}&q-key-time={sign_time}&q-header-list=host&q-url-param-list={}&q-signature={}", crate::rpc_encode(access_key_id), query.split('&').filter_map(|item| item.split_once('=').map(|(key, _)| key)).collect::<Vec<_>>().join(";"), hex::encode(sign_mac.finalize().into_bytes())))
}

pub(crate) async fn list_objects(id: i64, bucket: &str, location: &str, prefix: &str, marker: &str) -> Result<Value, String> {
    if crate::account_cloud_type(id)? != "tencent" { return Err("当前账号不是腾讯云账号".into()); }
    let (access_key_id, access_key_secret) = crate::account_credentials(id)?; let mut query = "list-type=2&max-keys=1000&delimiter=%2F".to_string(); if !prefix.is_empty() { query.push_str(&format!("&prefix={}", crate::rpc_encode(prefix))); } if !marker.is_empty() { query.push_str(&format!("&continuation-token={}", crate::rpc_encode(marker))); } let host = format!("{bucket}.cos.{location}.myqcloud.com"); let authorization = cos_authorization_with_query(&access_key_id, &access_key_secret, &host, &query)?; let response = reqwest::Client::new().get(format!("https://{host}/?{query}")).header("Host", &host).header("Authorization", authorization).timeout(std::time::Duration::from_secs(25)).send().await.map_err(|error| format!("COS 请求失败: {error}"))?; let status = response.status(); let body = response.text().await.map_err(|error| error.to_string())?; if !status.is_success() { let message = xml_text(&body, "Message"); return Err(format!("COS 返回错误（{status}）：{}", if message.is_empty() { "请求被拒绝" } else { &message })); } let objects = xml_blocks(&body, "Contents").into_iter().map(|object| json!({"Key": xml_text(&object, "Key"), "Size": xml_text(&object, "Size"), "LastModified": xml_text(&object, "LastModified"), "ETag": xml_text(&object, "ETag")})).filter(|object| object.get("Key").and_then(Value::as_str).is_some_and(|key| !key.is_empty() && key != prefix)).collect::<Vec<_>>(); Ok(json!({"objects": objects, "prefixes": xml_blocks(&body, "CommonPrefixes").into_iter().map(|entry| xml_text(&entry, "Prefix")).filter(|value| !value.is_empty()).collect::<Vec<_>>(), "isTruncated": xml_text(&body, "IsTruncated").eq_ignore_ascii_case("true"), "nextMarker": xml_text(&body, "NextContinuationToken")}))
}

pub(crate) async fn get_acl(id: i64, bucket: &str, location: &str) -> Result<String, String> {
    if crate::account_cloud_type(id)? != "tencent" { return Err("当前账号不是腾讯云账号".into()); } let (access_key_id, access_key_secret) = crate::account_credentials(id)?; let host = format!("{bucket}.cos.{location}.myqcloud.com"); let authorization = cos_authorization_with_query(&access_key_id, &access_key_secret, &host, "acl")?; let response = reqwest::Client::new().get(format!("https://{host}/?acl")).header("Host", &host).header("Authorization", authorization).timeout(std::time::Duration::from_secs(25)).send().await.map_err(|error| format!("COS 请求失败: {error}"))?; let status = response.status(); let body = response.text().await.map_err(|error| error.to_string())?; if !status.is_success() { return Err(format!("COS 返回错误（{status}）：{}", xml_text(&body, "Code"))); } Ok(xml_text(&body, "Permission"))
}
